var n=`0591-shorwa`;var t=`world-0591`;var a=`AF`;var o=`south-asia`;var s=4;var r=133;var g={en:`Shorwa`,ua:`Шорва`};var m={en:`A traditional dish from Afghanistan, centered on lamb, yellow onion, garlic, potato. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Афганістан. Основні складники: ягнятина, жовта цибуля, часник, картопля. Домашній варіант із кількостями продуктів за етапами приготування.`};var l=[{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 95 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 95 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:95,i:[[`lamb`,690,`g`],[`water`,1500,`ml`],[`yellow-onion`,200,`g`],[`garlic`,3,`clove`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 35 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 35 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:35,i:[[`potato`,500,`g`],[`carrot`,270,`g`],[`turnip`,220,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`cilantro`,22,`g`]]}];var d={slug:n,id:t,country:`AF`,region:o,servings:4,minutes:133,title:g,text:m,steps:l};export{a as country,d as default,t as id,r as minutes,o as region,s as servings,n as slug,l as steps,m as text,g as title};